 border="0" cellspacing="2" id="idm140070402636776"> <tr> <th class="tl" colspan="1" rowspan="2"><div style="width: 200px;"><strong>Financial Instruments (Carrying Amount of Equity Securities) (Details) - USD ($)<br> $ in Millions</strong></div></th> <th class="th" colspan="2">12 Months Ended</th> </tr> <tr> <th class="th"><div>Dec. 31, 2020</div></th> <th class="th"><div>Dec. 31, 2019</div></th> </tr> <tr class="re"> <td class="pl " style="border-bottom: 0px;" valign="top"><a class="a" href="javascript:void(0);" onclick="top.Show.showAR( this, 'defref_us-gaap_ScheduleOfTradingSecuritiesAndOtherTradingAssetsLineItems', window );"><strong>Debt and Equity Securities, FV-NI [Line Items]</strong></a></td> <td class="text">&#160;<span></span> </td> <td class="text">&#160;<span></span> </td> </tr> <tr class="ro"> <td class="pl custom" style="border-bottom: 0px;" valign="top"><a class="a" href="javascript:void(0);" onclick="top.Show.showAR( this, 'defref_goog_ProceedsfromSaleofEquitySecuritiesFVNIHeldforinvestment', window );">Total sale price</a></td> <td class="nump">$ 4,767<span></span> </td> <td class="nump">$ 3,134<span></span> </td> </tr> <tr class="re"> <td class="pl custom" style="border-bottom: 0px;" valign="top"><a class="a" href="javascript:void(0);" onclick="top.Show.showAR( this, 'defref_goog_EquitySecuritiesFVNICostBasisOfSecuritiesSold', window );">Total

